package surf.varun.core.domain

import com.google.common.truth.Truth.assertThat
import com.google.common.truth.Truth.assertWithMessage
import org.junit.Test
import surf.varun.core.model.SkillLevel

/**
 * Golden cases generated by running the web's `calculator.js` over a grid of
 * inputs, so the Kotlin port is held to the exact same answers.
 */
class KiteCalculatorTest {
    private val warningKeys = mapOf(
        "warningInvalidWindSpeed" to KiteCalculator.Warning.INVALID_WIND_SPEED,
        "warningInvalidWeight" to KiteCalculator.Warning.INVALID_WEIGHT,
        "warningWeightTooLow" to KiteCalculator.Warning.WEIGHT_TOO_LOW,
        "warningSkillLevelRequired" to KiteCalculator.Warning.SKILL_LEVEL_REQUIRED,
        "warningWeightTooHigh" to KiteCalculator.Warning.WEIGHT_TOO_HIGH,
        "warningExtremeWind" to KiteCalculator.Warning.EXTREME_WIND,
        "warningLowWind" to KiteCalculator.Warning.LOW_WIND,
        "warningInsufficientWindWaves" to KiteCalculator.Warning.INSUFFICIENT_WIND_WAVES,
    )

    private val cases = javaClass.getResource("/calculator_golden.txt")!!.readText()
        .lines().filter { it.isNotBlank() && !it.startsWith("#") }
        .map { it.split('|') }

    @Test
    fun matchesWebImplementationForEveryGoldenCase() {
        assertThat(cases.size).isGreaterThan(1000)
        for (parts in cases) {
            val wind = parts[0].toDouble()
            val weight = parts[1].toDouble()
            val skill = SkillLevel.fromKey(parts[2])
            val label = "wind=$wind weight=$weight skill=${parts[2]}"
            assertWithMessage(label).that(KiteCalculator.validate(wind, weight, skill)).isEqualTo(warningKeys[parts[3]])
            if (skill != null) {
                assertWithMessage(label).that(KiteCalculator.kiteSize(wind, weight, skill)).isEqualTo(parts[4].toInt())
                assertWithMessage(label).that(KiteCalculator.boardSize(weight, skill).text).isEqualTo(parts[5])
            }
        }
    }

    @Test
    fun calculateReturnsNothingWhenThereIsAWarning() {
        assertThat(KiteCalculator.calculate(30.0, 80.0, null)).isNull()
        assertThat(KiteCalculator.calculate(4.0, 80.0, SkillLevel.BEGINNER_FLAT)).isNull()
        assertThat(KiteCalculator.calculate(18.0, 80.0, SkillLevel.INTERMEDIATE_FLAT))
            .isEqualTo(KiteCalculator.Result(12, KiteCalculator.Board.TwinTip(140, 39)))
    }

}
